package com.studenthub.controller;
import com.fasterxml.jackson.databind.ObjectMapper;import com.studenthub.dao.UserDAO;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.util.*;
@WebServlet(name="UserSearchServlet",urlPatterns="/users/search")
public class UserSearchServlet extends HttpServlet{private final UserDAO dao=new UserDAO();private final ObjectMapper json=new ObjectMapper();@Override protected void doGet(HttpServletRequest q,HttpServletResponse r)throws IOException{try{long me=(Long)q.getSession().getAttribute("userId");var rows=dao.searchPublicUsers(me,q.getParameter("q"),20);r.setContentType("application/json");r.setCharacterEncoding("UTF-8");json.writeValue(r.getWriter(),rows.stream().map(u->Map.of("userId",u.userId(),"studentId",u.studentId()==null?"":u.studentId(),"fullName",u.fullName(),"role",u.role(),"avatarUrl",u.avatarUrl()==null?"":q.getContextPath()+"/profile/photo/"+u.avatarUrl(),"presenceLabel",u.getPresenceLabel(),"activeNow",u.isActiveNow())).toList());}catch(Exception e){getServletContext().log("User search failed: "+e.getClass().getName());r.sendError(500);}}}
